
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ityh_optx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ityh_optx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.011966555420280e+01, -9.913591219705042e+00, -9.624048003507600e+00, -9.221486053703332e+00, -8.670285659329776e+00, -7.932152626285446e+00, -6.975048975227596e+00, -5.790685687621325e+00, -4.422259913406413e+00, -3.003031067188730e+00, -1.825899664309705e+00, -1.287498239042031e+00, -1.079679835027643e+00, -8.102211375066358e-01, -4.607324590515511e-01, -1.665857885369129e-01, -2.550538885465519e-02, -1.098159709300950e-03, -1.076685012640493e-05, -1.503194116197278e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


